#include <bits/stdc++.h>
using namespace std;
int n,A[24],C[24]; unordered_map<int,array<int,2>> memo;
array<int,2> solve(int R){auto it=memo.find(R);if(it!=memo.end())return it->second;int active=0;for(int i=0;i<n;i++)if((R>>i&1)&&(A[i]&R))active|=1<<i;if(!active)return {0,0};int lo=100,hi=-1;for(int i=0;i<n;i++)if(C[i]&active){auto q=solve(R&~C[i]);lo=min(lo,1+q[1]);hi=max(hi,1+q[0]);}return memo[R]={lo,hi};}
bool connected(){int r=1;for(int k=0;k<n;k++)for(int i=0;i<n;i++)if(r>>i&1)r|=A[i];return r==(1<<n)-1;}
void test(long long &count,int &mx,int &ms){for(int i=0;i<n;i++)C[i]=A[i]|1<<i;memo.clear();auto q=solve((1<<n)-1);count++;mx=max(mx,q[0]);ms=max(ms,q[1]);if(max(q[0],q[1])>(3*n+6)/7){cout<<"VIOLATION "<<n<<" "<<q[0]<<" "<<q[1]<<" edges ";for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)if(A[i]>>j&1)cout<<i<<","<<j<<" ";cout<<endl;exit(0);}}
int main(int argc,char**argv){if(string(argv[1])=="all"){for(n=3;n<=7;n++){long long count=0;int mx=0,ms=0;vector<pair<int,int>> es;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)es.push_back({i,j});for(int mask=0;mask<(1<<es.size());mask++){fill(A,A+24,0);for(int k=0;k<(int)es.size();k++)if(mask>>k&1){auto [i,j]=es[k];A[i]|=1<<j;A[j]|=1<<i;}if(connected())test(count,mx,ms);}cout<<n<<" connected labeled "<<count<<" max "<<mx<<" "<<ms<<endl;}}else{mt19937 rng(222);for(n=8;n<=22;n++){long long count=0;int mx=0,ms=0;for(int z=0;z<3000;z++){fill(A,A+24,0);for(int i=1;i<n;i++){int j=rng()%i;A[i]|=1<<j;A[j]|=1<<i;}if(z%2)for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)if(rng()%100<12){A[i]|=1<<j;A[j]|=1<<i;}test(count,mx,ms);}cout<<n<<" seeded trees and sparse connected graphs "<<count<<" max "<<mx<<" "<<ms<<endl;}}}
